/bin/bash -lc "date -u && python - <<'PY'
import numpy as np
from sim import Sim
best=[]
for hip in np.linspace(-1.0,1.0,9):
  for knee in np.linspace(0.2,1.6,8):
    for ank in np.linspace(-1.0,0.8,10):
      for torso in np.linspace(-0.8,0.8,9):
        sim=Sim(); h=sim.home_ctrl(); c=h.copy()
        c[2]=hip; c[7]=hip; c[3]=knee; c[8]=knee; c[4]=ank; c[9]=ank; c[10]=torso
        ok=True
        for i in range(300):
          sim.data.ctrl[:]=c; sim.step()
          if sim.pelvis_position()[2]<0.2:
            ok=False; break
        p=sim.pelvis_position(); up=sim.torso_up()
        if ok and up>0.55 and p[2]>0.23:
          best.append((p[0],sim.distance_to_target(),hip,knee,ank,torso,p[2],up))
best.sort(reverse=True,key=lambda x:x[0])
print('count stable',len(best))
for r in best[:30]:
  print('x%.3f d%.3f hip%.2f knee%.2f ank%.2f torso%.2f z%.3f up%.3f'%r)
PY"
